-- #7. All match mutations serialize on the existing room row lock.
alter table private.arena_courses add column definition jsonb;
alter table private.arena_players
  add column stage text not null default 'atStart' check (stage in
    ('atStart','practice','walking','challenge','choosingRoute','finished','departed')),
  add column target_node text,
  add column challenge_id text,
  add column route_choice text check (route_choice in ('standard','bonus'));
create table private.arena_challenges (
  id text primary key, algorithm text not null, slot text not null,
  document jsonb not null, unique (algorithm, slot),
  check (document->'definition'->>'id' = id),
  check (document->'definition'->>'algorithm' = algorithm),
  check (document->'definition'->>'slot' = slot)
);
create table private.arena_arrivals (
  room_id uuid not null, user_id uuid not null, node_id text not null,
  method text not null check (method in ('location','organiserApproval')),
  confirmed_at timestamptz not null default clock_timestamp(),
  primary key (room_id,user_id,node_id),
  foreign key (room_id,user_id) references private.arena_players(room_id,user_id)
);
create table private.arena_submissions (
  room_id uuid not null, user_id uuid not null, challenge_id text not null references private.arena_challenges,
  command_id uuid not null, answer jsonb not null, correct boolean not null,
  accepted_at timestamptz not null default clock_timestamp(),
  primary key (room_id,user_id,challenge_id),
  foreign key (room_id,user_id) references private.arena_players(room_id,user_id)
);
create table private.arena_rewards (
  room_id uuid not null, user_id uuid not null, slot text not null,
  points integer not null,
  primary key (room_id,user_id,slot),
  foreign key (room_id,user_id) references private.arena_players(room_id,user_id),
  check ((slot in ('first','standardMiddle','third') and points in (0,20)) or
    (slot='bonusMiddle' and points in (0,40)) or (slot='finish' and points=20))
);
create table private.arena_arrival_approvals (
  id uuid primary key default gen_random_uuid(), room_id uuid not null, user_id uuid not null,
  node_id text not null, issuer_id uuid not null references auth.users(id),
  created_at timestamptz not null default clock_timestamp(),
  expires_at timestamptz not null default clock_timestamp() + interval '2 minutes',
  used_at timestamptz,
  foreign key (room_id,user_id) references private.arena_players(room_id,user_id)
);
create index arena_approvals_issuer on private.arena_arrival_approvals(issuer_id,created_at);
create index arena_approvals_player on private.arena_arrival_approvals(room_id,user_id,used_at);
alter table private.arena_challenges enable row level security;
alter table private.arena_arrivals enable row level security;
alter table private.arena_submissions enable row level security;
alter table private.arena_rewards enable row level security;
alter table private.arena_arrival_approvals enable row level security;
revoke all on all tables in schema private from public,anon,authenticated;

create function private.arena_immutable() returns trigger language plpgsql set search_path='' as $$
begin raise exception 'Match submissions and rewards are immutable'; end;
$$;
create trigger arena_rewards_immutable before update or delete on private.arena_rewards
  for each row execute function private.arena_immutable();
create trigger arena_submissions_immutable before update or delete on private.arena_submissions
  for each row execute function private.arena_immutable();
create function private.arena_time(value timestamptz) returns text
language sql immutable set search_path='' as $$
  select to_char(value at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"');
$$;
-- A shared ledger entry becomes visible only when BOTH answers exist. Even a
-- player's own score must not reveal correctness through a pending reward.
create function private.arena_reward_released(room_id uuid, slot text) returns boolean
language sql stable set search_path='' as $$
  select $2 not in ('first','third') or (select count(*)=2
    from private.arena_submissions s join private.arena_challenges c on c.id=s.challenge_id
    where s.room_id=$1 and c.slot=$2);
$$;
create function private.arena_rate_limited() returns void language plpgsql set search_path='' as $$
begin raise exception using errcode='P0001',message=
  '{"code":"rateLimited","message":"Wait before requesting another arrival override.","retryAfterSeconds":60}'; end;
$$;
-- Organisers are provisioned by an administrator through trusted app_metadata.
-- A room creator, nickname or user_metadata never grants this capability.
create function private.arena_issue_arrival_approval(match_id text, player_id text, node_id text)
returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare principal uuid:=auth.uid(); room private.arena_rooms; player private.arena_players;
  proof private.arena_arrival_approvals; course jsonb;
begin
  if principal is null then perform private.arena_fail('unauthenticated','Restore your organiser session.'); end if;
  if not exists (select 1 from auth.users u where u.id=principal
    and u.raw_app_meta_data->'arenaOrganiser'='true'::jsonb) then
    perform private.arena_fail('invalidApproval','An authenticated organiser is required.');
  end if;
  perform pg_advisory_xact_lock(hashtextextended('organiser:'||principal::text,0));
  if (select count(*) from private.arena_arrival_approvals a where a.issuer_id=principal
    and a.created_at>clock_timestamp()-interval '1 minute') >= 30 then
    perform private.arena_rate_limited();
  end if;
  select * into room from private.arena_rooms r where r.id::text=match_id for update;
  select * into player from private.arena_players p where p.room_id=room.id and p.user_id::text=player_id;
  if player.user_id is null or room.phase in ('finished','incomplete') then
    perform private.arena_fail('invalidApproval','Choose an active player and arrival.');
  end if;
  select c.definition into course from private.arena_courses c where c.id=room.course_id and c.version=room.course_version;
  if not ((player.stage='atStart' and node_id=course->'stops'->>'start') or
    (player.stage='walking' and node_id=player.target_node)) then
    perform private.arena_fail('invalidApproval','That arrival is not currently available.');
  end if;
  insert into private.arena_arrival_approvals(room_id,user_id,node_id,issuer_id)
    values(room.id,player.user_id,node_id,principal) returning * into proof;
  return jsonb_build_object('approvalID',proof.id,'expiresAt',private.arena_time(proof.expires_at));
end;
$$;
create function public.arena_issue_arrival_approval(match_id text,player_id text,node_id text)
returns jsonb language sql security invoker set search_path='' as $$
  select private.arena_issue_arrival_approval(match_id,player_id,node_id);
$$;
revoke all on function public.arena_issue_arrival_approval(text,text,text) from public,anon;
grant execute on function public.arena_issue_arrival_approval(text,text,text) to authenticated;

create function private.arena_verify_arrival(room private.arena_rooms,node_id text,evidence jsonb)
returns text language plpgsql set search_path='' as $$
#variable_conflict use_variable
declare principal uuid:=auth.uid(); course jsonb; policy jsonb; fix jsonb; coord jsonb;
  lat double precision; lon double precision; accuracy double precision; captured timestamptz;
  age double precision; distance double precision; approval private.arena_arrival_approvals;
begin
  select c.definition into course from private.arena_courses c where c.id=room.course_id and c.version=room.course_version;
  if jsonb_typeof(evidence) is distinct from 'object' or
    (select count(*) from jsonb_object_keys(evidence))<>1 then
    perform private.arena_fail('invalidCommand','Provide one arrival evidence type.');
  end if;
  if evidence ? 'organiserApproval' then
    if jsonb_typeof((evidence->'organiserApproval')->'approvalID') is distinct from 'string'
      or (evidence->'organiserApproval') - 'approvalID' <> '{}'::jsonb then
      perform private.arena_fail('invalidApproval','Request a fresh organiser approval.');
    end if;
    -- Issuance is capped per organiser; redemption is single-use and capped per
    -- player. Invalid IDs reveal no approval details and never consume a proof.
    if (select count(*) from private.arena_arrival_approvals a where a.room_id=room.id
      and a.user_id=principal and a.used_at>clock_timestamp()-interval '1 minute')>=5 then
      perform private.arena_rate_limited();
    end if;
    select * into approval from private.arena_arrival_approvals a
      where a.id::text=(evidence->'organiserApproval')->>'approvalID'
      and a.room_id=room.id and a.user_id=principal and a.node_id=node_id
      and a.used_at is null and a.expires_at>clock_timestamp() for update;
    if not found then perform private.arena_fail('invalidApproval','Request a fresh organiser approval for this arrival.'); end if;
    update private.arena_arrival_approvals set used_at=clock_timestamp() where id=approval.id;
    return 'organiserApproval';
  elsif evidence ? 'location' then
    if (evidence->'location') - 'fix' <> '{}'::jsonb then
      perform private.arena_fail('invalidCommand','Provide a location fix.');
    end if;
    fix:=(evidence->'location')->'fix'; coord:=fix->'coordinate'; policy:=course->'arrivalPolicy';
    if jsonb_typeof(fix) is distinct from 'object' or not fix ?& array['coordinate','capturedAt','horizontalAccuracyMetres']
      or fix-array['coordinate','capturedAt','horizontalAccuracyMetres']<>'{}'::jsonb
      or jsonb_typeof(coord) is distinct from 'object' or not coord ?& array['latitude','longitude']
      or coord-array['latitude','longitude']<>'{}'::jsonb
      or jsonb_typeof(coord->'latitude') is distinct from 'number'
      or jsonb_typeof(coord->'longitude') is distinct from 'number'
      or jsonb_typeof(fix->'horizontalAccuracyMetres') is distinct from 'number'
      or jsonb_typeof(fix->'capturedAt') is distinct from 'string' then
      perform private.arena_fail('invalidCommand','Provide coordinates, accuracy and capture time.');
    end if;
    begin
      lat:=(coord->>'latitude')::double precision; lon:=(coord->>'longitude')::double precision;
      accuracy:=(fix->>'horizontalAccuracyMetres')::double precision; captured:=(fix->>'capturedAt')::timestamptz;
    exception when others then perform private.arena_fail('invalidCommand','Invalid location fix.'); end;
    if lat not between -90 and 90 or lon not between -180 and 180 then
      perform private.arena_fail('invalidCommand','Coordinates are out of range.'); end if;
    age:=extract(epoch from clock_timestamp()-captured);
    if not isfinite(captured) or age<0 or age>(policy->>'maximumFixAgeSeconds')::double precision then
      perform private.arena_fail('staleLocation','Get a fresh location fix.'); end if;
    if accuracy<0 or accuracy>(policy->>'maximumHorizontalAccuracyMetres')::double precision then
      perform private.arena_fail('inaccurateLocation','Wait for a more accurate location fix.'); end if;
    select n->'coordinate' into coord from jsonb_array_elements(course->'nodes') n where n->>'id'=node_id;
    distance:=6371008.8*2*asin(sqrt(least(1.0,
      power(sin(radians(lat-(coord->>'latitude')::double precision)/2),2)+
      cos(radians(lat))*cos(radians((coord->>'latitude')::double precision))*
      power(sin(radians(lon-(coord->>'longitude')::double precision)/2),2))));
    if distance>(policy->>'radiusMetres')::double precision then
      perform private.arena_fail('outsideArrivalRadius','Move closer to the checkpoint.'); end if;
    if not (select c.surveyed from private.arena_courses c where c.id=room.course_id and c.version=room.course_version) then
      perform private.arena_fail('serviceUnavailable','This course awaits survey. Use an organiser-approved demo arrival.'); end if;
    return 'location';
  else perform private.arena_fail('invalidCommand','Unknown arrival evidence.'); end if;
end;
$$;

create function private.arena_navigation(course jsonb,branch text,target text) returns jsonb
language plpgsql immutable set search_path='' as $$
#variable_conflict use_variable
declare edge_id jsonb; edge jsonb; route jsonb; current_node text:=course->'stops'->>'start';
  source_node text; collecting boolean:=false; ids jsonb:='[]';
begin
  source_node:=case target when course->'stops'->>'first' then course->'stops'->>'start'
    when course->'stops'->>'third' then course->'stops'->>(case branch when 'bonus' then 'bonusMiddle' else 'standardMiddle' end)
    when course->'stops'->>'finish' then course->'stops'->>'third' else course->'stops'->>'first' end;
  select r into route from jsonb_array_elements(course->'routes') r where r->>'branch'=coalesce(branch,'standard');
  for edge_id in select value from jsonb_array_elements(route->'edgeIDs') loop
    if current_node=source_node then collecting:=true; end if;
    select e into edge from jsonb_array_elements(course->'edges') e where e->'id'=edge_id;
    current_node:=case when edge->>'from'=current_node then edge->>'to' else edge->>'from' end;
    if collecting then ids:=ids||jsonb_build_array(edge_id); end if;
    exit when current_node=target;
  end loop;
  return jsonb_build_object('nextStop',target,'edgeIDs',ids);
end;
$$;

create or replace function private.arena_snapshot(match_id text) returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare principal uuid:=auth.uid(); room private.arena_rooms; p private.arena_players;
  course jsonb; players jsonb:='[]'; standings jsonb:='[]'; submissions jsonb; feedback jsonb;
  available jsonb; navigation jsonb; learning jsonb; result jsonb; progress jsonb; stage jsonb;
  score integer; pending integer; remaining integer; awards jsonb; f jsonb; answers jsonb;
  s record; departed uuid; winner uuid;
begin
  if principal is null then perform private.arena_fail('unauthenticated','Restore your player session.'); end if;
  select * into room from private.arena_rooms r where r.id::text=match_id and private.arena_is_member(r.id) for share;
  if not found then perform private.arena_fail('notMember','This session is not a member of that room.'); end if;
  select c.definition into course from private.arena_courses c where c.id=room.course_id and c.version=room.course_version;
  for p in select * from private.arena_players a where a.room_id=room.id order by a.seat loop
    select coalesce(sum(r.points),0),coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'slot',case when r.slot<>'finish' then r.slot end,'points',r.points)) order by
      case r.slot when 'first' then 1 when 'standardMiddle' then 2 when 'bonusMiddle' then 2 when 'third' then 3 else 4 end),'[]')
      into score,awards from private.arena_rewards r where r.room_id=room.id and r.user_id=p.user_id
      and private.arena_reward_released(room.id,r.slot);
    select coalesce(sum((c.document->'definition'->>'maximumPoints')::integer),0) into pending
      from private.arena_submissions a join private.arena_challenges c on c.id=a.challenge_id
      where a.room_id=room.id and a.user_id=p.user_id and not private.arena_reward_released(room.id,c.slot);
    remaining:=case when p.route_choice='standard' then 80 else 100 end -
      (select coalesce(sum(case r.slot when 'bonusMiddle' then 40 else 20 end),0)
        from private.arena_rewards r where r.room_id=room.id and r.user_id=p.user_id);
    stage:=case p.stage when 'walking' then jsonb_build_object('walking',jsonb_build_object('target',p.target_node))
      when 'challenge' then jsonb_build_object('challenge',jsonb_build_object('challengeID',p.challenge_id))
      else jsonb_build_object(p.stage,'{}'::jsonb) end;
    progress:=jsonb_strip_nulls(jsonb_build_object('id',p.user_id,'nickname',p.nickname,
      'algorithmConfirmed',p.algorithm_confirmed,'ready',p.ready,'connection','online','stage',stage,
      'routeChoice',p.route_choice,'arrivals',(select coalesce(jsonb_agg(jsonb_build_object('nodeID',a.node_id,'method',a.method)
        order by a.confirmed_at,a.node_id),'[]') from private.arena_arrivals a where a.room_id=room.id and a.user_id=p.user_id),
      'completedChallengeIDs',(select coalesce(jsonb_agg(a.challenge_id order by a.accepted_at,a.challenge_id),'[]')
        from private.arena_submissions a where a.room_id=room.id and a.user_id=p.user_id),
      'releasedScore',score,'pendingRewardMaximum',pending,'remainingAvailablePoints',remaining));
    players:=players||jsonb_build_array(progress);
    standings:=standings||jsonb_build_array(jsonb_strip_nulls(jsonb_build_object('playerID',p.user_id,
      'routeChoice',p.route_choice,'score',score,'awards',awards)));
  end loop;
  if room.phase='incomplete' then
    select user_id into departed from private.arena_players a where a.room_id=room.id and a.stage='departed' order by a.seat limit 1;
    result:=jsonb_build_object('incomplete',jsonb_build_object('departedPlayerID',departed,'standings',standings));
  elsif room.phase='finished' then
    if standings->0->'score'=standings->1->'score' then result:=jsonb_build_object('draw',jsonb_build_object('standings',standings));
    else winner:=case when (standings->0->>'score')::integer>(standings->1->>'score')::integer
      then (standings->0->>'playerID')::uuid else (standings->1->>'playerID')::uuid end;
      result:=jsonb_build_object('winner',jsonb_build_object('playerID',winner,'standings',standings)); end if;
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('challengeID',a.challenge_id,'commandID',a.command_id,
    'answer',a.answer,'acceptedAt',private.arena_time(a.accepted_at)) order by a.accepted_at,a.challenge_id),'[]')
    into submissions from private.arena_submissions a where a.room_id=room.id and a.user_id=principal;
  feedback:='[]';
  for s in select a.*,c.slot,c.document from private.arena_submissions a join private.arena_challenges c on c.id=a.challenge_id
    where a.room_id=room.id and a.user_id=principal order by a.accepted_at,a.challenge_id loop
    if not private.arena_reward_released(room.id,s.slot) then
      feedback:=feedback||jsonb_build_array(jsonb_build_object('pending',jsonb_build_object('challengeID',s.challenge_id)));
    else
      select jsonb_agg(jsonb_build_object('playerID',a.user_id,'answer',a.answer,'isCorrect',a.correct,
        'awardedPoints',coalesce(r.points,0)) order by member.seat) into answers
        from private.arena_submissions a join private.arena_players member on member.room_id=a.room_id and member.user_id=a.user_id
        left join private.arena_rewards r on r.room_id=a.room_id and r.user_id=a.user_id and r.slot=s.slot
        where a.room_id=room.id and a.challenge_id=s.challenge_id
        and (s.slot in ('first','third') or a.user_id=principal);
      f:=jsonb_build_object('challengeID',s.challenge_id,'correctAnswer',s.document->'correctAnswer',
        'explanation',s.document->'explanation','workedSteps',s.document->'workedSteps',
        'workedStepTraceIndices',s.document->'workedStepTraceIndices','trace',s.document->'trace','answers',answers);
      feedback:=feedback||jsonb_build_array(jsonb_build_object('released',jsonb_build_object('feedback',f)));
    end if;
    if s.slot='learningCheck' then learning:=jsonb_build_object('challengeID',s.challenge_id,'firstAnswer',s.answer,
      'answeredAt',private.arena_time(s.accepted_at),'nodeCorrect',(s.answer->'transfer')->'nodeID'=s.document->'correctAnswer'->'transfer'->'nodeID',
      'reasonCorrect',(s.answer->'transfer')->'reasonID'=s.document->'correctAnswer'->'transfer'->'reasonID'); end if;
  end loop;
  select * into p from private.arena_players a where a.room_id=room.id and a.user_id=principal;
  select coalesce(jsonb_agg(c.document->'definition'),'[]') into available from private.arena_challenges c
    where c.algorithm=room.algorithm and room.phase<>'incomplete' and
    ((p.stage in ('practice','challenge') and c.id=p.challenge_id) or
      (p.stage='finished' and c.slot='learningCheck' and learning is null));
  if p.stage='walking' and room.phase<>'incomplete' then
    navigation:=private.arena_navigation(course,p.route_choice,p.target_node); end if;
  return jsonb_strip_nulls(jsonb_build_object('contractVersion',1,'revision',room.revision,
    'serverTime',private.arena_time(clock_timestamp()),'room',jsonb_build_object('matchID',room.id,'roomCode',room.code,
      'creatorID',room.creator_id,'course',jsonb_build_object('id',room.course_id,'version',room.course_version),
      'algorithm',room.algorithm,'phase',room.phase,'players',players,'result',result),
    'viewer',jsonb_build_object('playerID',principal,'submissions',submissions,'feedback',feedback,
      'availableChallenges',available,'navigation',navigation,'learningCheck',learning)));
end;
$$;

-- Preserve the lobby implementation; its receipts automatically use the richer snapshot.
alter function private.arena_command(jsonb) rename to arena_lobby_command;
revoke execute on function private.arena_lobby_command(jsonb) from authenticated;
create function private.arena_command(command jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare principal uuid:=auth.uid(); command_id uuid; action_name text; payload jsonb; scope jsonb;
  room private.arena_rooms; player private.arena_players; previous private.arena_command_receipts;
  course jsonb; slot text; challenge private.arena_challenges; answer jsonb; valid boolean;
  method text; target text; result jsonb; correct boolean;
begin
  if principal is null then perform private.arena_fail('unauthenticated','Restore your player session.'); end if;
  if jsonb_typeof(command) is distinct from 'object' or not command ?& array['contractVersion','id','scope','action']
    or command-array['contractVersion','id','scope','action']<>'{}'::jsonb then
    perform private.arena_fail('invalidCommand','Expected a MatchCommand envelope.'); end if;
  if command->'contractVersion' is distinct from '1'::jsonb then
    perform private.arena_fail('incompatibleContract','This server supports contract version 1.'); end if;
  begin command_id:=(command->>'id')::uuid;
  exception when others then perform private.arena_fail('invalidCommand','A UUID command ID is required.'); end;
  if command_id is null then perform private.arena_fail('invalidCommand','A UUID command ID is required.'); end if;
  perform pg_advisory_xact_lock(hashtextextended(principal::text,0));
  select * into previous from private.arena_command_receipts r where r.user_id=principal and r.command_id=command_id;
  if found then
    if previous.command<>command then perform private.arena_fail('idempotencyConflict','That command ID has a different payload.'); end if;
    return previous.receipt;
  end if;
  if jsonb_typeof(command->'action') is distinct from 'object' or
    (select count(*) from jsonb_object_keys(command->'action'))<>1 then
    perform private.arena_fail('invalidCommand','Exactly one action is required.'); end if;
  select key,value into action_name,payload from jsonb_each(command->'action');
  if jsonb_typeof(payload) is distinct from 'object' then
    perform private.arena_fail('invalidCommand','Action parameters must be an object.'); end if;
  if action_name in ('createRoom','joinRoom','selectAlgorithm','confirmAlgorithm','setReady') then
    return private.arena_lobby_command(command); end if;
  if jsonb_typeof(command->'scope') is distinct from 'object' or (command->'scope')-'match'<>'{}'::jsonb
    or jsonb_typeof((command->'scope')->'match') is distinct from 'object' then
    perform private.arena_fail('invalidCommand','This action requires match scope.'); end if;
  scope:=(command->'scope')->'match';
  if not scope ?& array['matchID','course','expectedRevision']
    or scope-array['matchID','course','expectedRevision']<>'{}'::jsonb
    or jsonb_typeof(scope->'matchID') is distinct from 'string'
    or jsonb_typeof(scope->'expectedRevision') is distinct from 'number'
    or scope->>'expectedRevision' !~ '^[0-9]{1,9}$' then
    perform private.arena_fail('invalidCommand','Match, course and integer revision are required.'); end if;
  select * into room from private.arena_rooms r where r.id::text=scope->>'matchID'
    and private.arena_is_member(r.id) for update;
  if not found then perform private.arena_fail('notMember','This session is not a member of that room.'); end if;
  if scope->'course' is distinct from jsonb_build_object('id',room.course_id,'version',room.course_version) then
    perform private.arena_fail('incompatibleCourse','Refresh the supported course version.'); end if;
  if (scope->>'expectedRevision')::integer<>room.revision then
    perform private.arena_fail('staleRevision','Refresh the room before trying again.',room.revision); end if;
  select * into player from private.arena_players p where p.room_id=room.id and p.user_id=principal;
  select c.definition into course from private.arena_courses c where c.id=room.course_id and c.version=room.course_version;
  if room.phase='incomplete' or (room.phase='finished' and action_name<>'submitAnswer') then
    perform private.arena_fail('invalidPhase','This match has ended.'); end if;
  if action_name='start' then
    if payload<>'{}'::jsonb or principal<>room.creator_id then
      perform private.arena_fail('invalidCommand','Only the room creator can start.'); end if;
    if room.phase<>'lobby' then perform private.arena_fail('invalidPhase','The match already started.'); end if;
    if (select count(*) from private.arena_players p where p.room_id=room.id)<>2 or
      exists(select 1 from private.arena_players p where p.room_id=room.id and (not p.ready or not p.algorithm_confirmed)) then
      perform private.arena_fail('algorithmNotConfirmed','Both players must confirm and become ready.'); end if;
    if exists(select 1 from private.arena_players p where p.room_id=room.id and p.start_arrival_method is null) then
      perform private.arena_fail('arrivalRequired','Both players must verify arrival at the shared start.'); end if;
    update private.arena_players set stage='practice',challenge_id=(select c.id from private.arena_challenges c
      where c.algorithm=room.algorithm and c.slot='practice') where room_id=room.id;
    update private.arena_rooms set phase='practice' where id=room.id;
  elsif action_name='confirmArrival' or action_name='finish' then
    if action_name='finish' then
      if not payload ? 'evidence' or payload-'evidence'<>'{}'::jsonb then
        perform private.arena_fail('invalidCommand','Provide finish evidence.'); end if;
      target:=course->'stops'->>'finish';
    else
      if not payload ?& array['nodeID','evidence'] or payload-array['nodeID','evidence']<>'{}'::jsonb
        or jsonb_typeof(payload->'nodeID') is distinct from 'string' then
        perform private.arena_fail('invalidCommand','Provide an arrival node and evidence.'); end if;
      target:=payload->>'nodeID';
    end if;
    if not ((room.phase='lobby' and player.stage='atStart' and target=course->'stops'->>'start' and action_name='confirmArrival') or
      (player.stage='walking' and target=player.target_node)) then
      perform private.arena_fail('arrivalRequired','Follow the next confirmed route before arriving.'); end if;
    if exists(select 1 from private.arena_arrivals a where a.room_id=room.id and a.user_id=principal and a.node_id=target) then
      perform private.arena_fail('invalidPhase','This arrival was already confirmed.'); end if;
    if target=course->'stops'->>'finish' and
      (select count(*) from private.arena_rewards r where r.room_id=room.id and r.user_id=principal)<>3 then
      perform private.arena_fail('arrivalRequired','Complete all three chosen checkpoints before finishing.'); end if;
    method:=private.arena_verify_arrival(room,target,payload->'evidence');
    insert into private.arena_arrivals(room_id,user_id,node_id,method) values(room.id,principal,target,method);
    if room.phase='lobby' then update private.arena_players set start_arrival_method=method where room_id=room.id and user_id=principal;
    elsif target=course->'stops'->>'finish' then
      insert into private.arena_rewards values(room.id,principal,'finish',20);
      update private.arena_players set stage='finished',target_node=null,challenge_id=null where room_id=room.id and user_id=principal;
    else
      slot:=case target when course->'stops'->>'first' then 'first' when course->'stops'->>'third' then 'third'
        when course->'stops'->>'standardMiddle' then 'standardMiddle' else 'bonusMiddle' end;
      update private.arena_players set stage='challenge',target_node=null,challenge_id=(select c.id from private.arena_challenges c
        where c.algorithm=room.algorithm and c.slot=slot) where room_id=room.id and user_id=principal;
    end if;
  elsif action_name='chooseRoute' then
    if not payload ? 'branch' or payload-'branch'<>'{}'::jsonb or jsonb_typeof(payload->'branch') is distinct from 'string'
      or payload->>'branch' not in ('standard','bonus') then perform private.arena_fail('invalidCommand','Choose standard or bonus.'); end if;
    if player.route_choice is not null then perform private.arena_fail('routeAlreadyLocked','The middle checkpoint is already locked.'); end if;
    if player.stage<>'choosingRoute' then perform private.arena_fail('invalidPhase','Complete checkpoint one before choosing.'); end if;
    update private.arena_players set route_choice=payload->>'branch',stage='walking',
      target_node=course->'stops'->>(case payload->>'branch' when 'standard' then 'standardMiddle' else 'bonusMiddle' end)
      where room_id=room.id and user_id=principal;
  elsif action_name='submitAnswer' then
    if not payload ?& array['challengeID','answer'] or payload-array['challengeID','answer']<>'{}'::jsonb
      or jsonb_typeof(payload->'challengeID') is distinct from 'string' then
      perform private.arena_fail('invalidCommand','Provide a challenge and answer.'); end if;
    select * into challenge from private.arena_challenges c where c.id=payload->>'challengeID' and c.algorithm=room.algorithm;
    if not found then perform private.arena_fail('challengeUnavailable','That challenge is unavailable.'); end if;
    slot:=challenge.slot; answer:=payload->'answer';
    if exists(select 1 from private.arena_submissions s where s.room_id=room.id and s.user_id=principal and s.challenge_id=challenge.id) then
      perform private.arena_fail('alreadySubmitted','Your first answer is already recorded.'); end if;
    if not ((player.stage in ('practice','challenge') and player.challenge_id=challenge.id) or
      (player.stage='finished' and slot='learningCheck')) then
      perform private.arena_fail('challengeUnavailable','Follow the checkpoint and route prerequisites.'); end if;
    valid:=false;
    if challenge.document->'definition'->'action' ? 'selectNode' then
      valid:=jsonb_typeof((answer->'node')->'nodeID')='string' and answer-'node'='{}'::jsonb and (answer->'node')-'nodeID'='{}'::jsonb
        and challenge.document->'definition'->'action'->'selectNode'->'options' @> jsonb_build_array((answer->'node')->'nodeID');
    elsif challenge.document->'definition'->'action' ? 'enterCost' then
      valid:=jsonb_typeof((answer->'cost')->'value')='number' and answer-'cost'='{}'::jsonb and (answer->'cost')-'value'='{}'::jsonb
        and (answer->'cost')->>'value' ~ '^-?[0-9]{1,15}$';
    elsif challenge.document->'definition'->'action' ? 'selectRoute' then
      valid:=jsonb_typeof((answer->'route')->'optionID')='string' and answer-'route'='{}'::jsonb and (answer->'route')-'optionID'='{}'::jsonb
        and exists(select 1 from jsonb_array_elements(challenge.document->'definition'->'action'->'selectRoute'->'options') o
          where o->'id'=(answer->'route')->'optionID');
    else
      valid:=jsonb_typeof((answer->'transfer')->'nodeID')='string' and jsonb_typeof((answer->'transfer')->'reasonID')='string'
        and answer-'transfer'='{}'::jsonb and (answer->'transfer')-array['nodeID','reasonID']='{}'::jsonb
        and challenge.document->'definition'->'action'->'transfer'->'nodeOptions' @> jsonb_build_array((answer->'transfer')->'nodeID')
        and exists(select 1 from jsonb_array_elements(challenge.document->'definition'->'action'->'transfer'->'reasons') o
          where o->'id'=(answer->'transfer')->'reasonID');
    end if;
    if not coalesce(valid,false) then perform private.arena_fail('invalidCommand','Use an answer supported by this challenge.'); end if;
    correct:=answer=challenge.document->'correctAnswer';
    insert into private.arena_submissions(room_id,user_id,challenge_id,command_id,answer,correct)
      values(room.id,principal,challenge.id,command_id,answer,correct);
    if slot in ('first','standardMiddle','bonusMiddle','third') then
      insert into private.arena_rewards values(room.id,principal,slot,
        case when correct then (challenge.document->'definition'->>'maximumPoints')::integer else 0 end); end if;
    if slot='first' then update private.arena_players set stage='choosingRoute',challenge_id=null where room_id=room.id and user_id=principal;
    elsif slot<>'learningCheck' then
      target:=course->'stops'->>(case slot when 'practice' then 'first' when 'third' then 'finish' else 'third' end);
      update private.arena_players set stage='walking',target_node=target,challenge_id=null where room_id=room.id and user_id=principal;
    end if;
  elsif action_name='leave' then
    if payload<>'{}'::jsonb then perform private.arena_fail('invalidCommand','Departure takes no parameters.'); end if;
    update private.arena_players set stage='departed',target_node=null,challenge_id=null where room_id=room.id and user_id=principal;
    update private.arena_rooms set phase='incomplete' where id=room.id;
  else perform private.arena_fail('invalidCommand','Unknown match action.'); end if;
  if (action_name<>'leave' and room.phase<>'lobby') or action_name='start' then
    update private.arena_rooms set phase=case
      when not exists(select 1 from private.arena_players p where p.room_id=room.id and p.stage<>'finished') then 'finished'
      when not exists(select 1 from private.arena_players p where p.room_id=room.id
        and not(p.stage='finished' or (p.stage='walking' and p.target_node=course->'stops'->>'finish'))) then 'awaitingFinish'
      when exists(select 1 from private.arena_submissions s where s.room_id=room.id) then 'active' else 'practice' end where id=room.id;
  end if;
  update private.arena_rooms set revision=revision+1 where id=room.id returning * into room;
  insert into public.arena_invalidations("matchID",revision) values(room.id,room.revision)
    on conflict("matchID") do update set revision=excluded.revision;
  result:=jsonb_build_object('commandID',command_id,'acceptedRevision',room.revision,'snapshot',private.arena_snapshot(room.id::text));
  insert into private.arena_command_receipts(user_id,command_id,room_id,command,receipt) values(principal,command_id,room.id,command,result);
  return result;
end;
$$;
create or replace function public.arena_command(command jsonb) returns jsonb
language sql security invoker set search_path='' as $$ select private.arena_command(command); $$;
revoke all on all functions in schema private from public,anon,authenticated;
grant execute on function private.arena_is_member(uuid),private.arena_command(jsonb),private.arena_snapshot(text),
  private.arena_issue_arrival_approval(text,text,text) to authenticated;

